seo.schema:
{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "HomeAndConstructionBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "image": "{lb_logo}",
            "description": "{business} connects {state} property owners with trained water and storm damage restoration specialists, providing 24/7 emergency water extraction, structural drying, and flood, storm, and sewage cleanup for homes and businesses.",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            },
            "priceRange": "$$",
            "openingHours": "Mo-Su 00:00-23:59",
            "address": {
                "@type": "PostalAddress",
                "addressLocality": "{city}",
                "addressRegion": "{SS}",
                "postalCode": "{zip}",
                "addressCountry": "US"
            }
        },
        {
            "@type": "WebSite",
            "@id": "{website}/#website",
            "url": "{website}",
            "name": "{business}",
            "publisher": {
                "@id": "{website}/#localbusiness"
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "ContactPage",
            "@id": "{website}/contact-us/#webpage",
            "url": "{website}/contact-us/",
            "name": "Contact Us",
            "description": "Get in touch with {business} for inquiries, questions, or to request our services.",
            "about": {
                "@id": "{website}/#localbusiness"
            },
            "mainEntity": {
                "@id": "{website}/#localbusiness"
            }
        },
        {
            "@type": "ContactPoint",
            "@id": "{website}/contact-us/#contactpoint",
            "telephone": "{tel}",
            "contactType": "customer service",
            "areaServed": "US"
        }
    ]
}

{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "AboutPage",
            "@id": "{website}/about-us/#webpage",
            "url": "{website}/about-us",
            "name": "About Us",
            "description": "Learn more about {business}, our mission, and our commitment to quality restoration services.",
            "mainEntity": {
                "@id": "{website}/#localbusiness"
            }
        }
    ]
}
